// n8n Code node (JavaScript)
// Entrada esperada (exemplo):
// [
//   { json: { data: "<string JSON do /api/v4/leads/custom_fields>" } }
// ]
// Saída: um item por custom field com informações úteis.

function parseMaybeJson(v) {
  if (v == null) return null;
  if (typeof v === 'object') return v;
  try { return JSON.parse(String(v)); } catch { return null; }
}

const inputItems = $input.all();
const out = [];

for (const it of inputItems) {
  const root = parseMaybeJson(it.json?.data);
  if (!root) {
    out.push({ json: { error: 'Não foi possível parsear json.data' } });
    continue;
  }

  const fields = root?._embedded?.custom_fields || [];
  if (!Array.isArray(fields) || fields.length === 0) {
    out.push({ json: { warning: 'Nenhum custom field encontrado em _embedded.custom_fields' } });
    continue;
  }

  for (const f of fields) {
    const enumsArr = Array.isArray(f.enums)
      ? f.enums.map(e => ({
          id: e.id ?? null,
          value: e.value ?? null,
          sort: e.sort ?? null,
        }))
      : null;

    const enum_values = enumsArr ? enumsArr.map(e => e.value).join(', ') : null;

    out.push({
      json: {
        id: f.id ?? null,
        name: f.name ?? null,
        type: f.type ?? null,
        code: f.code ?? null,
        entity_type: f.entity_type ?? null,
        group_id: f.group_id ?? null,
        sort: f.sort ?? null,

        is_api_only: !!f.is_api_only,
        is_predefined: !!f.is_predefined,
        is_deletable: !!f.is_deletable,

        required_statuses: Array.isArray(f.required_statuses) ? f.required_statuses : [],
        hidden_statuses: Array.isArray(f.hidden_statuses) ? f.hidden_statuses : [],
        chained_lists: f.chained_lists ?? null,

        link: f._links?.self?.href ?? null,

        // enums já prontos para planilha
        enums: enumsArr,
        enum_values, // "valor1, valor2, ..."
      }
    });
  }
}

return out;

